INSERT INTO `cancellation_reviews` (`id`, `order_id`, `customer_id`, `reason`, `comment`, `created_at`, `updated_at`) VALUES
(1, 2549, 4872, 'Не подошло время', '', '2025-12-21 13:13:47', '2025-12-21 13:13:47'),
(2, 2768, 6340, 'Передумал(а)', '', '2026-01-01 19:02:11', '2026-01-01 19:02:11'),
(3, 3193, 3566, 'Не подошло время', '', '2026-01-26 13:17:28', '2026-01-26 13:17:28'),
(4, 3859, 3594, 'Другое', 'Машина вашей компании сломалась поэтому дали другому компании следующий раз обратимся и почините ваш транспорт пожалуйста ', '2026-02-23 10:38:36', '2026-02-23 10:38:36'),
(5, 3931, 6971, 'Другое', 'Я не отменила заказ 2 день собрала все ковры и жду когда придут и отнимут их☹️', '2026-02-25 15:31:48', '2026-02-25 15:31:48'),
(6, 4537, 7318, 'Передумал(а)', '', '2026-03-14 13:26:42', '2026-03-14 13:26:42'),
(7, 4611, 7351, 'Нашёл(а) другую компанию', '', '2026-03-23 11:33:20', '2026-03-23 11:33:20'),
(8, 4637, 7362, 'Не смог(ла) дозвониться', '', '2026-03-23 14:46:14', '2026-03-23 14:46:14'),
(9, 4775, 7443, 'Передумал(а)', 'Ваши доставщики хамло \nПроявили неуважение клиенту и сказали чтобы я сама спустилась 12-го этажа и им ковры спустило нашла охрану чтобы шлагбаум открыли то есть это должна была я сделать сама они всячески причину искали чтобы не добраться до моего дома до моей квартиры меня как клиента не должно волновать как они заберут мои ковры с квартиры им нужно было пройти 50 шагов им было это лень чтобы забрать два тоненьких ковра ', '2026-03-26 12:02:35', '2026-03-26 12:02:35'),
(10, 5224, 7667, 'Не подошло время', 'Лучше будед поменять режим сбора и возврата ковров. Забирать на чистку с утра до обеда, а возвращать когда люди будут дома, т.е вечернее время. У вас же все наоборот. Желаю вам удачи   и\nпроцветания в вашем деле.', '2026-04-12 15:31:54', '2026-04-12 15:31:54'),
(11, 5359, 333, 'Не подошло время', '', '2026-04-17 06:54:50', '2026-04-17 06:54:50');
